// F§4有限占用强制到期接N真实阶段；业务结果成立后才在同候选采用S0收据。
#include "facility_exact_phase.hpp"
#include "resident/kernel/exact_complete_world.hpp"
#include "resident/kernel/world_bundle.hpp"
#include <algorithm>
#include <stdexcept>
#include <tuple>
namespace hanmo::resident { namespace {
struct Failure {RuleError error;};
void fail(const char* code,ErrorKind kind=ErrorKind::rule){throw Failure{common_failure(code,"facility_claims",kind).error};}
template<class T>T take(Outcome<T> result){if(!result.ok)throw Failure{std::move(result.error)};return std::move(result.value);}
template<class T,class F>Outcome<T> guard(F fn){try{return {true,fn(),{}};}catch(Failure& e){return {false,{},std::move(e.error)};}catch(const std::bad_alloc&){return {false,{},common_failure("FacilityPhaseResourceExhausted","facility_claims",ErrorKind::internal).error};}catch(const std::length_error&){return {false,{},common_failure("FacilityPhaseResourceExhausted","facility_claims",ErrorKind::internal).error};}}
auto kind_key(const FacilityHolderKind& k){return std::tie(k.kind,k.owner_domain,k.activity_kind);}
void bound(const WorldBundle& w,const CompleteExactWorldReadBindings& access){if(!w.facility_claims||&access.facility_claims!=&*w.facility_claims)fail("FacilityBindingCandidateMismatch");}
const FacilityHolderRegistration& holder(const FacilityClaim2& claim,const CompleteExactWorldReadBindings& access){auto actual=take(access.facility_holders.read_facility_holder_kind(claim.holder));const FacilityHolderRegistration* found=nullptr;for(const auto& h:access.facility_holder_handlers)if(kind_key(h.selection.holder)==kind_key(actual)){if(found)fail("DuplicateFacilityHolderAdapter");found=&h;}if(!found||!found->until_stage)fail("MissingFacilityHolderAdapter",ErrorKind::unsupported_capability);return *found;}
const FacilityClaim2& claim(const FacilityClaimsState& state,const StableId& id){const FacilityClaim2* out=nullptr;for(const auto& c:state.claims)if(c.claim_id==id){if(out)fail("DuplicateFacilityClaim");out=&c;}if(!out)fail("StaleFacilityDuePrediction");return *out;}
void selected(const WorldBundle& w,const CompleteExactWorldReadBindings& access,const std::vector<FacilityHolderPhaseSelection>& expected){bound(w,access);take(validate_facility_holder_registry(access.facility_holder_handlers,access.facility_holders));if(expected.size()!=access.facility_holder_handlers.size())fail("FacilityHolderSelectionMismatch");for(const auto& e:expected){const FacilityHolderRegistration* found=nullptr;for(const auto& h:access.facility_holder_handlers)if(kind_key(e.selection.holder)==kind_key(h.selection.holder)){if(found)fail("DuplicateFacilityHolderAdapter");found=&h;}if(!found||found->selection.profile_id!=e.selection.profile_id||found->selection.version!=e.selection.version||!found->until_stage||*found->until_stage!=e.until_stage)fail("FacilityHolderSelectionMismatch");}}
}
Outcome<ExactPhaseRegistration> make_facility_exact_phase_registration(const std::vector<FacilityHolderRegistration>& compiled){return guard<ExactPhaseRegistration>([&]{
    auto expected=take(compile_facility_holder_profiles(compiled));if(expected.empty())fail("MissingFacilityHolderAdapter",ErrorKind::unsupported_capability);std::vector<ExactStage> stages;
    for(const auto& h:expected)if(std::find(stages.begin(),stages.end(),h.until_stage)==stages.end())stages.push_back(h.until_stage);
    ExactPhaseRegistration r;r.provider=ExactProviderId::facility_claims;r.profile_id="facility_claim_history_v2";r.version=2;r.stages=std::move(stages);r.effect_writer_keys={"facility_claim_until_resolution"};
    r.validate_author_selection=[](const WorldBundle& w){return guard<Done>([&]{auto lease=take(w.complete_exact_time_bindings());const auto& a=lease->reads();selected(w,a,a.runtime.facility_holder_profiles);return Done{};});};
    r.validate_world_sources=[](const WorldBundle& w,const WorldMoment& at){return guard<Done>([&]{auto lease=take(w.complete_exact_time_bindings());const auto& a=lease->reads();bound(w,a);take(validate_facility_claims(a.facility_claims,a.runtime.facility_claims,at,a.facility_sources));return Done{};});};
    r.predict=[](const WorldBundle& w,const WorldMoment& from,const WorldMoment& through){return guard<std::vector<ExactEventPrediction>>([&]{auto lease=take(w.complete_exact_time_bindings());const auto& a=lease->reads();bound(w,a);auto dues=take(predict_facility_claim_dues(a.facility_claims,from,through));std::vector<ExactEventPrediction> out;for(const auto& due:dues){const auto& c=claim(a.facility_claims,due.claim_id);const auto& h=holder(c,a);out.push_back({due.due_at,*h.until_stage,{"facility_claims","facility_claim",c.claim_id},2,due.claim_set_revision});}return out;});};
    r.apply_due=[](WorldBundle& w,const ExactEventPrediction& p,ExactPhaseWriteContext& writes){return guard<ExactEventApplied>([&]{auto lease=take(w.complete_exact_time_bindings());const auto& a=lease->reads();bound(w,a);if(p.source_schema!=2||p.actual_source_basis.domain!="facility_claims"||p.actual_source_basis.kind!="facility_claim")fail("InvalidFacilityDueSource");const auto& c=claim(a.facility_claims,p.actual_source_basis.id);const auto& h=holder(c,a);if(*h.until_stage!=p.stage)fail("FacilityDueStageMismatch");FacilityClaimDue due{c.claim_id,c.slot_ref,p.dependency_revision,p.at};auto ref=take(apply_facility_claim_due_in_candidate(w,*w.facility_claims,a.runtime.facility_claims,due,a.facility_holder_handlers,a.facility_holders,a.facility_sources,writes));auto actual=take(read_facility_claim_receipt(*w.facility_claims,ref));return ExactEventApplied{actual.source_result_ref,actual.source_schema};});};
    r.validate_applied_source=[](const WorldBundle& w,const ExactEventApplied& applied){return guard<Done>([&]{auto lease=take(w.complete_exact_time_bindings());const auto& a=lease->reads();bound(w,a);bool found=false;for(const auto& history:a.facility_claims.slot_histories)if(!history.mutations.empty()){const auto& last=history.mutations.back();if(last.source_schema==applied.source_schema&&same_source_ref(last.source_result_ref,applied.applied_result)){take(a.facility_sources.validate_mutation_source(history.slot_ref,last));found=true;}}if(!found)fail("FacilityAppliedSourceMissing");return Done{};});};
    return r;
});}
}
